<!-- ═══ HERO ══════════════════════════════════════════════ -->\n<section class=\"page-hero family-premium-hero\"><div class=\"study-hero-slides\" style=\"--n:4\"><img class=\"study-premium-backdrop study-hero-slide\" style=\"--i:0\" alt=\"\" fetchpriority=\"high\" src=\"/images/canada_bg.jpg\"/><img class=\"study-premium-backdrop study-hero-slide\" style=\"--i:1\" alt=\"\" loading=\"lazy\" src=\"/images/australia_bg.jpg\"/><img class=\"study-premium-backdrop study-hero-slide\" style=\"--i:2\" alt=\"\" loading=\"lazy\" src=\"/images/uk_bg.jpg\"/><img class=\"study-premium-backdrop study-hero-slide\" style=\"--i:3\" alt=\"\" loading=\"lazy\" src=\"/images/germany_bg.jpg\"/></div><img class=\"study-fly study-fly-1\" src=\"/images/suvira-fly-butterfly.png\" alt=\"\" aria-hidden=\"true\" width=\"60\" height=\"60\"/><img class=\"study-fly study-fly-2\" src=\"/images/suvira-fly-butterfly.png\" alt=\"\" aria-hidden=\"true\" width=\"60\" height=\"60\"/><img class=\"study-fly study-fly-3\" src=\"/images/suvira-fly-butterfly.png\" alt=\"\" aria-hidden=\"true\" width=\"60\" height=\"60\"/><img class=\"study-fly study-fly-4\" src=\"/images/suvira-fly-butterfly.png\" alt=\"\" aria-hidden=\"true\" width=\"60\" height=\"60\"/><img class=\"study-fly study-fly-5\" src=\"/images/suvira-fly-butterfly.png\" alt=\"\" aria-hidden=\"true\" width=\"60\" height=\"60\"/>\n<div class=\"container\">\n<div class=\"page-hero-badge\"><i class=\"fas fa-calculator\"></i> OFFICIAL EVALUATION</div>\n<h1 class=\"page-hero-title\">Free Eligibility Check</h1>\n<p class=\"page-hero-subtitle\">\n                    Instant points calculation &amp; profile assessment for Canada Express Entry, Australia Skilled Visas, Germany Opportunity Card, UK &amp; European Pathways.\n                </p>\n<div class=\"flag-strip\" style=\"justify-content: center; margin-top: 20px;\">\n<div class=\"flag-chip\"><img alt=\"Canada\" src=\"https://flagcdn.com/w40/ca.png\"/> Canada PR</div>\n<div class=\"flag-chip\"><img alt=\"Australia\" src=\"https://flagcdn.com/w40/au.png\"/> Australia PR</div>\n<div class=\"flag-chip\"><img alt=\"Germany\" src=\"https://flagcdn.com/w40/de.png\"/> Germany Card</div>\n<div class=\"flag-chip\"><img alt=\"UK\" src=\"https://flagcdn.com/w40/gb.png\"/> UK Visa</div>\n<div class=\"flag-chip\"><img alt=\"NZ\" src=\"https://flagcdn.com/w40/nz.png\"/> NZ Pathway</div>\n<div class=\"flag-chip\"><img alt=\"Ireland\" src=\"https://flagcdn.com/w40/ie.png\"/> Ireland EU</div>\n<div class=\"flag-chip\"><img alt=\"Singapore\" src=\"https://flagcdn.com/w40/sg.png\"/> Singapore EP</div>\n<div class=\"flag-chip\"><img alt=\"Russia\" src=\"https://flagcdn.com/w40/ru.png\"/> MBBS Russia</div>\n<div class=\"flag-chip\"><img alt=\"Ukraine\" src=\"https://flagcdn.com/w40/ua.png\"/> MBBS Ukraine</div>\n</div>\n</div>\n</section>\n<!-- Stats Strip -->\n<div class=\"stats-strip\">\n<div class=\"stats-inner\">\n<div class=\"stat-chip\">\n<div style=\"width:34px;height:34px;background:rgba(13,59,46,0.08);border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--site-action);font-size:0.85rem;flex-shrink:0;\">\n<i class=\"fas fa-users\"></i></div>\n<div><strong>5,000+</strong><br/><span>Profiles Assessed</span></div>\n</div>\n<div class=\"stat-chip\">\n<div style=\"width:34px;height:34px;background:rgba(13,59,46,0.08);border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--site-action);font-size:0.85rem;flex-shrink:0;\">\n<i class=\"fas fa-clock\"></i></div>\n<div><strong>24 Hours</strong><br/><span>Response Time</span></div>\n</div>\n<div class=\"stat-chip\">\n<div style=\"width:34px;height:34px;background:rgba(13,59,46,0.08);border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--site-action);font-size:0.85rem;flex-shrink:0;\">\n<i class=\"fas fa-award\"></i></div>\n<div><strong>5,000+</strong><br/><span>Profiles Guided</span></div>\n</div>\n<div class=\"stat-chip\">\n<div style=\"width:34px;height:34px;background:rgba(13,59,46,0.08);border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--site-action);font-size:0.85rem;flex-shrink:0;\">\n<i class=\"fas fa-shield-alt\"></i></div>\n<div><strong>100%</strong><br/><span>Confidential</span></div>\n</div>\n<div class=\"stat-chip\">\n<div style=\"width:34px;height:34px;background:rgba(13,59,46,0.08);border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--site-action);font-size:0.85rem;flex-shrink:0;\">\n<i class=\"fas fa-globe\"></i></div>\n<div><strong>7+</strong><br/><span>Core Destinations</span></div>\n</div>\n</div>\n</div>\n<!-- ═══ MAIN LAYOUT ════════════════════════════════════════ -->\n<div class=\"page-wrapper\">\n<!-- ── FORM ─────────────────────────── -->\n<div class=\"form-card\">\n<div class=\"form-card-header\">\n<div>\n<i class=\"fas fa-clipboard-check\"></i>\n</div>\n<div>\n<h2>Eligibility Profile Submission Form</h2>\n<p>All fields marked * are required. We will email your eligibility report.</p>\n</div>\n</div>\n<div class=\"form-body\">\n<form id=\"eligibilityForm\" onsubmit=\"handleEligibilitySubmit(event)\">\n<!-- 1. Personal Information -->\n<div class=\"section-divider\">\n<div class=\"sdiv-icon\"><i class=\"fas fa-user\"></i></div>\n<h3>Personal Information</h3>\n</div>\n<div class=\"fg-2\">\n<div class=\"fgroup\">\n<label>Full Name *</label>\n<input id=\"eName\" name=\"Full_Name\" placeholder=\"Enter your full name\" required=\"\" type=\"text\"/>\n</div>\n<div class=\"fgroup\">\n<label>Date of Birth *</label>\n<input id=\"eDob\" name=\"Date_of_Birth\" required=\"\" type=\"date\"/>\n</div>\n</div>\n<div class=\"fg-2\">\n<div class=\"fgroup\">\n<label>Phone / WhatsApp *</label>\n<input id=\"ePhone\" name=\"Phone_/_WhatsApp\" inputmode=\"tel\" pattern=\"[0-9+\\s\\-()]{10,20}\" minlength=\"10\" maxlength=\"18\" title=\"Please enter a valid phone number with at least 10 digits (no alphabets)\" onblur=\"if(typeof suviraValidatePhoneInput==='function')suviraValidatePhoneInput(this);\" placeholder=\"+91 99403 52086\" required=\"\" type=\"tel\"/>\n</div>\n<div class=\"fgroup\">\n<label>Email Address *</label>\n<input id=\"eEmail\" name=\"Email_Address\" placeholder=\"your.email@example.com\" required=\"\" type=\"email\"/>\n</div>\n</div>\n<!-- 2. Education & Language -->\n<div class=\"section-divider\">\n<div class=\"sdiv-icon\"><i class=\"fas fa-graduation-cap\"></i></div>\n<h3>Education &amp; Language</h3>\n</div>\n<div class=\"fg-2\">\n<div class=\"fgroup\">\n<label>Highest Education *</label>\n<select id=\"eEdu\" name=\"Highest_Education\" required=\"\">\n<option disabled=\"\" selected=\"\" value=\"\">Select qualification</option>\n<option value=\"PhD\">Doctoral / Ph.D.</option>\n<option value=\"Master's Degree\">Master's Degree / PG Diploma</option>\n<option value=\"Bachelor's Degree\">Bachelor's Degree (3+ years)</option>\n<option value=\"Diploma\">Post-Secondary Diploma (2 yr)</option>\n<option value=\"12th / HSC\">12th Standard / HSC</option>\n</select>\n</div>\n<div class=\"fgroup\">\n<label>English Language Test Result</label>\n<select id=\"eIelts\" name=\"English_Language_Test\">\n<option value=\"Not Taken Yet\">Not Taken Yet</option>\n<option value=\"IELTS CLB 9 (8,7,7,7)\">IELTS CLB 9 — 8, 7, 7, 7</option>\n<option value=\"IELTS CLB 8 (7.5,6.5,6.5,6.5)\">IELTS CLB 8 — 7.5, 6.5, 6.5, 6.5\n                                    </option>\n<option value=\"IELTS CLB 7 (6.0 each)\">IELTS CLB 7 — 6.0 each band</option>\n<option value=\"PTE / OET / CELPIP\">PTE / OET / CELPIP</option>\n</select>\n</div>\n</div>\n<!-- 3. Work Experience -->\n<div class=\"section-divider\">\n<div class=\"sdiv-icon\"><i class=\"fas fa-briefcase\"></i></div>\n<h3>Work Experience</h3>\n</div>\n<div class=\"fg-3\">\n<div class=\"fgroup\">\n<label>Years of Experience *</label>\n<select id=\"eExp\" name=\"Years_of_Experience\" required=\"\">\n<option disabled=\"\" selected=\"\" value=\"\">Select</option>\n<option value=\"Less than 1 year\">Less than 1 year</option>\n<option value=\"1–2 Years\">1 – 2 Years</option>\n<option value=\"3–4 Years\">3 – 4 Years</option>\n<option value=\"5+ Years\">5+ Years</option>\n</select>\n</div>\n<div class=\"fgroup\">\n<label>Occupation / Field</label>\n<input id=\"eOcc\" name=\"Occupation_or_Field\" placeholder=\"e.g. IT Engineer, Nurse\" type=\"text\"/>\n</div>\n<div class=\"fgroup\">\n<label>Marital Status</label>\n<select id=\"eMarital\" name=\"Marital_Status\">\n<option value=\"Single\">Single</option>\n<option value=\"Married\">Married</option>\n<option value=\"Married (Spouse migrating too)\">Married (Spouse too)</option>\n</select>\n</div>\n</div>\n<!-- 4. Target Country -->\n<div class=\"section-divider\">\n<div class=\"sdiv-icon\"><i class=\"fas fa-globe-americas\"></i></div>\n<h3>Target Country &amp; Visa Type</h3>\n</div>\n<div class=\"fg-2\">\n<div class=\"fgroup\">\n<label>Preferred Destination *</label>\n<select id=\"eCountry\" name=\"Preferred_Destination\" required=\"\">\n<option disabled=\"\" selected=\"\" value=\"\">Select country</option>\n<option value=\"Canada\">🇨🇦 Canada</option>\n<option value=\"Australia\">🇦🇺 Australia</option>\n<option value=\"Germany\">🇩🇪 Germany</option>\n<option value=\"United Kingdom\">🇬🇧 United Kingdom</option>\n<option value=\"UAE\">🇦🇪 UAE</option>\n<option value=\"Japan\">🇯🇵 Japan</option>\n<option value=\"Russia\">🇷🇺 Russia</option>\n<option value=\"New Zealand\">🇳🇿 New Zealand</option>\n<option value=\"Ireland\">🇮🇪 Ireland</option>\n<option value=\"Singapore\">🇸🇬 Singapore</option>\n<option value=\"Ukraine\">🇺🇦 Ukraine</option>\n<option value=\"Other / Undecided\">🌍 Other / Undecided</option>\n</select>\n</div>\n<div class=\"fgroup\">\n<label>Visa Category</label>\n<select id=\"eVisa\" name=\"Visa_Category\">\n<option value=\"Permanent Residency (PR)\">Permanent Residency (PR)</option>\n<option value=\"Student / Study Visa\">Student / Study Visa</option>\n<option value=\"MBBS Abroad Admission\">MBBS Abroad Admission</option>\n<option value=\"Family Sponsorship\">Family Sponsorship</option>\n<option value=\"Visitor / Tourism Visa\">Visitor / Tourism Visa</option>\n<option value=\"Not Sure - Need Guidance\">Not Sure – Need Guidance</option>\n</select>\n</div>\n</div>\n<!-- 5. Additional Notes -->\n<div class=\"section-divider\">\n<div class=\"sdiv-icon\"><i class=\"fas fa-comment-dots\"></i></div>\n<h3>Additional Information <span style=\"font-weight:500;color:#94A3B8;text-transform:none;letter-spacing:0;\">(Optional)</span>\n</h3>\n</div>\n<div class=\"fg-1\">\n<div class=\"fgroup\">\n<label>Any specific requirements or questions?</label>\n<textarea id=\"eNotes\" name=\"Questions_or_Notes\" placeholder=\"e.g. Have a Canadian spouse, currently outside India, had a previous visa refusal, MBBS interested…\" rows=\"3\"></textarea>\n</div>\n</div>\n<!-- Submit -->\n<div class=\"submit-row\">\n<button class=\"submit-btn\" type=\"submit\">\n<i class=\"fas fa-paper-plane\"></i> Submit Profile for Free Assessment\n                            </button>\n<div class=\"submit-note\">\n<i class=\"fas fa-lock\"></i> Your data is 100% confidential. We never share your\n                                information.\n                            </div>\n</div>\n<!-- Success Message -->\n<div class=\"success-box\" id=\"successMsg\">\n<i class=\"fas fa-check-circle\"></i>\n<div>\n<strong>Profile Submitted Successfully!</strong><br/>\n                                Our Chennai immigration team will review your profile and contact you \n                            </div>\n</div>\n</form>\n</div>\n</div>\n<!-- ── SIDEBAR ───────────────────────── -->\n<aside class=\"sidebar\">\n<!-- Call to action -->\n<div class=\"call-card\">\n<i class=\"fas fa-headset\"></i>\n<h3>Prefer to Talk Directly?</h3>\n<p>Call or WhatsApp our Chennai immigration experts right now — available Mon–Sat, 9AM to 6PM.</p>\n<a class=\"call-btn\" href=\"tel:+919940352086\">\n<i class=\"fas fa-phone\"></i> +91 